function validate([board]) {
  if (!Array.isArray(board) || board.length !== 9 || board.some(line => !Array.isArray(line) || line.length !== 9)) return 'board must be 9 rows of 9 cells.';
  if (board.some(line => line.some(ch => !/^[1-9.]$/.test(ch)))) return "Each cell is a digit '1' to '9' or '.'.";
  const row = Array(9).fill(0), col = Array(9).fill(0), box = Array(9).fill(0), cells = [];
  for (let r = 0; r < 9; r++) for (let c = 0; c < 9; c++) {
    if (board[r][c] === '.') { cells.push(r * 9 + c); continue; }
    const bit = 1 << Number(board[r][c]), b = Math.floor(r / 3) * 3 + Math.floor(c / 3);
    if ((row[r] | col[c] | box[b]) & bit) return `The clue ${board[r][c]} at row ${r}, column ${c} repeats in its row, column or box.`;
    row[r] |= bit; col[c] |= bit; box[b] |= bit;
  }
  // Count completions, stopping at two, branching on the blank with the fewest options.
  let found = 0;
  const search = left => {
    if (left === 0) { found++; return; }
    let best = -1, bestFree = 0, bestCount = 10;
    for (let i = 0; i < left; i++) {
      const r = Math.floor(cells[i] / 9), c = cells[i] % 9, b = Math.floor(r / 3) * 3 + Math.floor(c / 3);
      const free = ~(row[r] | col[c] | box[b]) & 0x3fe;
      let n = 0;
      for (let x = free; x; x &= x - 1) n++;
      if (n < bestCount) { best = i; bestFree = free; bestCount = n; }
      if (n === 0) return;
    }
    [cells[best], cells[left - 1]] = [cells[left - 1], cells[best]];
    const r = Math.floor(cells[left - 1] / 9), c = cells[left - 1] % 9, b = Math.floor(r / 3) * 3 + Math.floor(c / 3);
    for (let d = 1; d <= 9 && found < 2; d++) {
      const bit = 1 << d;
      if (!(bestFree & bit)) continue;
      row[r] |= bit; col[c] |= bit; box[b] |= bit;
      search(left - 1);
      row[r] &= ~bit; col[c] &= ~bit; box[b] &= ~bit;
    }
  };
  search(cells.length);
  if (found === 0) return 'This board cannot be completed.';
  if (found > 1) return 'This board has more than one solution; the problem guarantees exactly one.';
  return null;
}

