function solveSudoku(board) {
  const rows = new Array(9).fill(0);
  const cols = new Array(9).fill(0);
  const boxes = new Array(9).fill(0);
  const given = board.flat().join('');

  for (let row = 0; row < 9; row++) {
    for (let col = 0; col < 9; col++) {
      if (board[row][col] === '.') continue;
      const bit = 1 << Number(board[row][col]);
      rows[row] |= bit;
      cols[col] |= bit;
      boxes[3 * Math.floor(row / 3) + Math.floor(col / 3)] |= bit;
    }
  }

  let cell = 0;
  let step = 1;
  while (cell < 81) {
    const row = Math.floor(cell / 9);
    const col = cell % 9;
    const box = 3 * Math.floor(row / 3) + Math.floor(col / 3);
    if (given[cell] === '.') {
      const old = board[row][col] === '.' ? 0 : Number(board[row][col]);
      if (old > 0) {
        rows[row] ^= 1 << old;
        cols[col] ^= 1 << old;
        boxes[box] ^= 1 << old;
      }
      let digit = old + 1;
      while (digit <= 9 && (rows[row] | cols[col] | boxes[box]) & (1 << digit)) digit++;
      if (digit <= 9) {
        rows[row] |= 1 << digit;
        cols[col] |= 1 << digit;
        boxes[box] |= 1 << digit;
        board[row][col] = String(digit);
        step = 1;
      } else {
        board[row][col] = '.';
        step = -1;
      }
    }
    cell += step;
  }
}

