function solveSudoku(board) {
  // Scan the whole grid for the first blank on every call and test each digit against its row, column and box.
  const fits = (row, col, ch) => {
    for (let k = 0; k < 9; k++) {
      if (board[row][k] === ch || board[k][col] === ch) return false;
      if (board[3 * Math.floor(row / 3) + Math.floor(k / 3)][3 * Math.floor(col / 3) + (k % 3)] === ch) return false;
    }
    return true;
  };
  const solve = () => {
    for (let row = 0; row < 9; row++) {
      for (let col = 0; col < 9; col++) {
        if (board[row][col] !== '.') continue;
        for (const ch of '123456789') {
          if (!fits(row, col, ch)) continue;
          board[row][col] = ch;
          if (solve()) return true;
          board[row][col] = '.';
        }
        return false;
      }
    }
    return true;
  };
  solve();
}

